"""Document tools: the final file is generated by code from the draft.

The writer (or the orchestrator) writes the content in the task's `data/` and
`generate_document` creates the Word, Excel, PowerPoint or PDF in `results/`, verifies
it by code and leaves images of the first pages in `data/views/` to check by eye that
the format looks right.
"""

from __future__ import annotations

import asyncio
import re
from pathlib import Path
from typing import Annotated, Any

from claude_agent_sdk import ToolAnnotations, tool

from aide.core import charts
from aide.core.context import SessionContext
from aide.core.documents import FORMATS, generate, verify
from aide.tools.server import error, log_factory, text


def _inside(path: Path, folder: Path) -> bool:
    try:
        return path.resolve().is_relative_to(folder.resolve())
    except (OSError, ValueError):
        return False


def _reply(v: Any) -> str:
    lines = [v.text() + "."]
    if v.views:
        lines.append(
            "Images of the first pages (open them with Read and check that they look right): "
            + ", ".join(str(p) for p in v.views)
        )
    if not v.ok:
        lines.append("Fix the problem and generate or check it again.")
    return "\n".join(lines)


@log_factory
def documents_tools(ses: SessionContext) -> list[Any]:
    """Builds the tools that generate and check documents such as docx, xlsx and pdf."""
    core = ses.core

    @tool(
        "generate_document",
        "Generates the final file (docx, xlsx, pptx or pdf) with code from a draft in the task "
        "folder and checks it (it opens, it is not empty, pages, sheets or slides). The draft is "
        'Markdown; for Excel, JSON {"sheets": [{"name", "columns", "rows"}]} (sheets with name, '
        "columns and rows; keep these keys) or Markdown tables; for PowerPoint, one slide per “# ” "
        "heading or separated with “---”, and “Notes: ...” lines go to the speaker notes. The file "
        "is saved in results/ and it returns images of the first pages for you to review.",
        {
            "format_": Annotated[str, "docx, xlsx, pptx or pdf"],
            "draft": Annotated[str, "Path of the draft inside the task folder (in data/)"],
            "name": Annotated[str, "Name of the final file, for example market_report.docx"],
            "expected": Annotated[
                int, "Pages, sheets or slides it should have (0 if it does not matter)"
            ],
        },
        annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False, openWorldHint=False),
    )
    async def generate_document(args: dict[str, Any]) -> dict[str, Any]:
        folder = ses.folder
        if folder is None or ses.task_id is None:
            return error("This can only be used inside a task.")
        format_ = str(args.get("format_", "")).lower().lstrip(".")
        if format_ not in FORMATS:
            return error(f"Format not supported: {format_}. Use docx, xlsx, pptx or pdf.")
        draft = Path(str(args.get("draft", ""))).expanduser()
        if not draft.is_absolute():
            draft = folder / draft
        if not draft.is_file() or not _inside(draft, folder):
            return error("The draft must be a file in this task's folder.")
        if _inside(draft, folder / "results"):
            return error("The draft goes in data/ (for example data/drafts/), not in results/.")
        name = re.sub(r"[^\w .,()-]", "_", Path(str(args.get("name", ""))).name).strip()
        if not name or name.startswith("."):
            name = f"{draft.stem}.{format_}"
        if Path(name).suffix.lower() != f".{format_}":
            name = f"{Path(name).stem}.{format_}"
        output = folder / "results" / name
        expected = int(args.get("expected") or 0) or None
        content = draft.read_text(encoding="utf-8", errors="replace")
        try:
            await asyncio.to_thread(generate, format_, content, output)
        except Exception as e:
            return error(f"Could not generate {name}: {type(e).__name__}: {str(e)[:300]}")
        v = await asyncio.to_thread(verify, output, expected, folder / "data" / "views")
        await core.tasks.log_file(ses.task_id, output, "result")
        await core.tasks.event(
            ses.task_id,
            "document",
            v.text(),
            {"path": str(output), "ok": v.ok, "views": [str(p) for p in v.views]},
        )
        return text(f"Generated {output}.\n{_reply(v)}")

    @tool(
        "verify_document",
        "Checks with code a docx, xlsx, pptx or pdf in the task folder or in a project: that it "
        "opens, that it is not empty and how many pages, sheets or slides it has. Returns images "
        "of the first pages so you can review the formatting.",
        {
            "path": Annotated[str, "Absolute path of the file"],
            "expected": Annotated[
                int, "Pages, sheets or slides it should have (0 if it does not matter)"
            ],
        },
        annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False, openWorldHint=False),
    )
    async def verify_document(args: dict[str, Any]) -> dict[str, Any]:
        folder = ses.folder
        if folder is None or ses.task_id is None:
            return error("This can only be used inside a task.")
        path = Path(str(args.get("path", ""))).expanduser()
        if not path.is_absolute():
            path = folder / path
        if not (_inside(path, folder) or _inside(path, core.paths.projects)):
            return error("Only files from this task or from the projects can be checked.")
        if path.suffix.lower().lstrip(".") not in FORMATS:
            return error("Only docx, xlsx, pptx or pdf files can be checked.")
        expected = int(args.get("expected") or 0) or None
        v = await asyncio.to_thread(verify, path, expected, folder / "data" / "views")
        await core.tasks.event(
            ses.task_id,
            "document",
            v.text(),
            {"path": str(path), "ok": v.ok, "views": [str(p) for p in v.views]},
        )
        return text(_reply(v))

    @tool(
        "generate_chart",
        "Generates a PNG chart with code (bars, horizontal bars or lines) from some figures and "
        "saves it in results/: the user gets it as an image in Telegram. Use it when the "
        "delivery compares figures (trends, usage, sales). One label per point and, in each "
        "series, one value per label. Look at the image with Read before delivering.",
        {
            "type": "object",
            "properties": {
                "kind": {"type": "string", "enum": list(charts.KINDS)},
                "title": {"type": "string"},
                "labels": {"type": "array", "items": {"type": "string"}},
                "series": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "name": {"type": "string"},
                            "values": {"type": "array", "items": {"type": "number"}},
                        },
                        "required": ["values"],
                    },
                },
                "axis_and": {"type": "string"},
                "stacked": {"type": "boolean"},
                "name": {"type": "string"},
            },
            "required": ["kind", "title", "labels", "series"],
        },
        annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False, openWorldHint=False),
    )
    async def generate_chart(args: dict[str, Any]) -> dict[str, Any]:
        folder = ses.folder
        if folder is None or ses.task_id is None:
            return error("This can only be used inside a task.")
        name = re.sub(r"[^\w .,()-]", "_", Path(str(args.get("name") or "chart")).stem).strip()
        output = folder / "results" / f"{name or 'chart'}.png"
        try:
            await asyncio.to_thread(
                charts.generate,
                output,
                str(args.get("kind") or ""),
                str(args.get("title") or ""),
                list(args.get("labels") or []),
                list(args.get("series") or []),
                axis_and=str(args.get("axis_and") or ""),
                stacked=bool(args.get("stacked")),
            )
        except charts.ChartError as e:
            return error(f"Could not make the chart: {e}.")
        await core.tasks.log_file(ses.task_id, output, "result")
        await core.tasks.event(ses.task_id, "chart", output.name, {"path": str(output)})
        return text(
            f"Chart saved in {output} ({output.stat().st_size // 1024} KB). Open it with Read and "
            "check that it reads well before delivering; the user will get it as an image."
        )

    return [generate_document, verify_document, generate_chart]
